# patch_s139_mushaf_ar_en_and_i18n_widgets.py
#
# Two things:
#
# 1) Al-Mushaf (mushaf_screen.dart + its loader) now only ever shows
#    Arabic or English, regardless of the app's global 5-language
#    setting (ar/en/fr/id/ur). AppSettings gets a `mushafStrings`
#    getter that clamps fr/id/ur down to English; the mushaf reader
#    and its loading screen read through that instead of the raw
#    `strings` getter. The rest of the app (studio, settings, home)
#    keeps all five languages untouched.
#
# 2) Wires up 123 previously-hardcoded-Arabic strings (translations.py)
#    into app_strings.dart's table, and connects the ones that live in
#    small, self-contained widgets: the color picker, the first-run
#    tour's title/skip, the stage preview's two overlay hints, and five
#    strings in the text editor's "text" tab. home_screen.dart,
#    sequence_screen.dart, and the about dialog carry the other ~100
#    keys in translations.py and are deliberately left for a follow-up
#    patch -- wiring those means walking a much bigger file and didn't
#    fit in one focused patch.
#
# Run from the project root.

from pathlib import Path

ROOT = Path(__file__).resolve().parent
LEDGER = []
MARKER = 'PATCH_S139_MUSHAF_AR_EN_AND_I18N_WIDGETS'


def _log(label, status):
    LEDGER.append((label, status))


def apply_literal(rel_path, old, new, label, skip_if=None):
    p = ROOT / rel_path
    if not p.exists():
        raise SystemExit(f"ERROR ({label}): {rel_path} not found under {ROOT}")
    text = p.read_text(encoding="utf-8")
    if skip_if and skip_if in text:
        _log(label, "SKIPPED-ALREADY")
        return
    n = text.count(old)
    if n != 1:
        raise SystemExit(f"ERROR ({label}): expected 1 match, found {n} in {rel_path} "
                          f"-- refusing to guess, no changes made.")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")
    _log(label, "APPLIED")


APP_STRINGS = "lib/i18n/app_strings.dart"
APP_SETTINGS = "lib/services/app_settings.dart"
MUSHAF = "lib/screens/mushaf_screen.dart"
MUSHAF_LOADER = "lib/screens/mushaf_loader_screen.dart"
